from datetime import datetime, timedelta, timezone
from decimal import Decimal
import json
import sqlite3
from unittest.mock import patch

import api_client
import api_server
import config
import database
import importers
import models
import support


def response(status, payload=None, text=None):
    """Build a real requests response without any socket or external HTTP access."""
    result = api_client.requests.Response()
    result.status_code = status
    result._content = (text if text is not None else json.dumps(payload)).encode('utf-8')
    result._content_consumed = True
    return result


class ApiTests(support.DatabaseCase):
    """Use a shared in-memory SQLite database so every Flask request opens its own connection."""

    def setUp(self):
        """Seed three sources and a profile, then freeze the clock for both HTTP and fallback."""
        super().setUp()
        uri = f'file:weekwise-{self._testMethodName}?mode=memory&cache=shared'
        anchor = database.get_connection(uri, uri=True)
        self.connection.backup(anchor)
        self.connection.close()
        self.connection = anchor
        self.addCleanup(anchor.close)
        self.app = api_server.create_app(uri, uri=True)
        self.app.testing = True
        self.client = self.app.test_client()
        clock = patch.object(config, 'local_now', side_effect=lambda now=None: now or support.NOW)
        clock.start()
        self.addCleanup(clock.stop)
        self.user = database.create_user(self.connection, 'Alex', now=support.NOW)
        self.save()
        for source, title, offset in (('unisport', 'Volleyball', 2), ('city', 'Jazz concert', 3)):
            start = support.NOW + timedelta(days=offset)
            row = support.record(source=source, external_id=source, title=title, sport=title,
                                  start=start, end=start + timedelta(hours=1),
                                  price=None, club_name='', club_category='')
            importers.save_records(self.connection, [row], source, self.taxonomy, now=support.NOW)
        self.event = self.scalar("SELECT id FROM events WHERE series_id=1")
        self.start = datetime(2026, 11, 3)
        self.end = datetime(2026, 11, 6)
        self.params = {'from': '2026-11-03', 'to': '2026-11-06'}

    def body(self, action='confirm', **changes):
        """Return a valid interaction body with optional boundary-test overrides."""
        body = {'user_id': self.user, 'event_id': self.event, 'action': action, 'rating': None}
        body.update(changes)
        return body

    def bridge_get(self, url, params=None, **options):
        """Connect requests mocks to Flask's real routing and JSON serialization in memory."""
        self.assertEqual(options['timeout'], config.API_TIMEOUT_SECONDS)
        self.assertFalse(options['allow_redirects'])
        path = url.removeprefix(config.API_BASE_URL)
        result = self.client.get(path, query_string=params)
        return response(result.status_code, text=result.get_data(as_text=True))

    def bridge_post(self, url, json=None, **options):
        """Execute real API transitions through Flask's test client, with no network."""
        self.assertEqual(url, config.API_BASE_URL + '/interactions')
        self.assertEqual(options['timeout'], config.API_TIMEOUT_SECONDS)
        self.assertFalse(options['allow_redirects'])
        result = self.client.post('/interactions', json=json)
        return response(result.status_code, text=result.get_data(as_text=True))

    def test_health_and_categories(self):
        """Expose only the version and public taxonomy with both configured color palettes."""
        health = self.client.get('/health')
        self.assertEqual(health.status_code, 200)
        self.assertEqual(health.json, {'status': 'ok', 'version': config.APP_VERSION})
        result = self.client.get('/categories')
        self.assertEqual(result.status_code, 200)
        directions = result.json['directions']
        self.assertEqual([row['key'] for row in directions], list(config.DIRECTION_LABELS))
        for direction in directions:
            self.assertEqual(direction['colors'], config.DIRECTION_COLORS[direction['key']])
            self.assertTrue(direction['bundles'])
        self.assertNotIn('friend_code', result.get_data(as_text=True))

    def test_api_can_start_before_the_first_streamlit_visit(self):
        """Initialize a fresh schema so API-first startup returns an empty list rather than 503."""
        uri = 'file:weekwise-api-first?mode=memory&cache=shared'
        anchor = database.get_connection(uri, uri=True)
        self.addCleanup(anchor.close)
        api_server.prepare_database(uri, uri=True)
        client = api_server.create_app(uri, uri=True).test_client()
        result = client.get('/events', query_string=self.params)
        self.assertEqual(result.status_code, 200)
        self.assertEqual(result.json, [])
        api_server.prepare_database(uri, uri=True)
        self.assertEqual(client.get('/health').status_code, 200)

    def test_events_exact_rows_nulls_and_integer_money(self):
        """Keep JSON identical to SQLite, including nullable fields and integers above 2**53."""
        rappen = 9007199254740993
        with self.connection:
            self.connection.execute('UPDATE series SET price_rappen=? WHERE id=?', (rappen, 1))
        result = self.client.get('/events', query_string=self.params)
        expected = database.get_event_records(self.connection, self.start, self.end)
        self.assertEqual(result.status_code, 200)
        self.assertEqual(result.json, expected)
        self.assertEqual(set(result.json[0]), set(config.EVENT_RECORD_FIELDS))
        self.assertIs(type(result.json[0]['price_rappen']), int)
        self.assertEqual(result.json[0]['price_rappen'], rappen)
        self.assertIsNone(result.json[-1]['price_rappen'])
        self.assertIsNone(result.json[-1]['club_id'])
        frame = database.get_events_df(self.connection, self.start, self.end)
        self.assertEqual(frame.loc[self.event, 'price_rappen'], rappen)
        event = models.event_from_row(frame.reset_index().to_dict('records')[0])
        self.assertEqual(event.price, Decimal('90071992547409.93'))
        single = self.client.get(f'/events/{self.event}')
        self.assertEqual(single.status_code, 200)
        self.assertEqual(single.json, expected[0])

    def test_half_open_range_and_filters(self):
        """Use a half-open range and combine source/category filters with AND."""
        query = {'from': '2026-11-03', 'to': '2026-11-04'}
        self.assertEqual(len(self.client.get('/events', query_string=query).json), 1)
        query.update(self.params, direction='sports', source='unisport')
        result = self.client.get('/events', query_string=query)
        self.assertEqual(len(result.json), 1)
        query['bundle'] = result.json[0]['bundle_key']
        self.assertEqual(len(self.client.get('/events', query_string=query).json), 1)
        query['source'] = 'city'
        self.assertEqual(self.client.get('/events', query_string=query).json, [])
        query = dict(self.params, bundle="unknown' OR 1=1 --")
        self.assertEqual(self.client.get('/events', query_string=query).json, [])
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM events'), 3)

    def test_missing_malformed_and_bounded_dates(self):
        """Reject missing/non-ISO dates, reversed/empty intervals and more than 120 days."""
        cases = ({}, {'from': '2026-11-03'}, {'to': '2026-11-04'},
                 {'from': '2026-02-30', 'to': '2026-11-04'},
                 {'from': '2026-1-1', 'to': '2026-11-04'},
                 {'from': '20261103', 'to': '2026-11-04'},
                 {'from': '2026-11-03T00:00:00', 'to': '2026-11-04'},
                 {'from': '2026-11-04', 'to': '2026-11-04'},
                 {'from': '2026-11-05', 'to': '2026-11-04'},
                 {'from': '2026-01-01', 'to': '2026-05-02'})
        for query in cases:
            with self.subTest(query=query):
                result = self.client.get('/events', query_string=query)
                self.assertEqual(result.status_code, 400)
                self.assertEqual(set(result.json), {'error'})
        query = {'from': '2026-01-01', 'to': '2026-05-01'}
        self.assertEqual(self.client.get('/events', query_string=query).status_code, 200)

    def test_not_found_and_methods_are_json(self):
        """Return JSON 404/405 responses for unknown occurrences, paths and unsupported verbs."""
        for path in ('/events/99999', '/events/0', '/events/-1', '/events/99999999999999999999',
                      '/unknown'):
            result = self.client.get(path)
            self.assertEqual(result.status_code, 404)
            self.assertIn('error', result.json)
        result = self.client.post('/health', json={})
        self.assertEqual(result.status_code, 405)
        self.assertIn('error', result.json)

    def test_post_confirmation_cancellation_and_unknown_references(self):
        """Return 201 for real state changes, 400 for a duplicate and 404 for unknown references."""
        result = self.client.post('/interactions', json=self.body())
        self.assertEqual(result.status_code, 201)
        stored = database.get_interaction(self.connection, self.user, self.event)
        self.assertEqual(result.json, stored)
        duplicate = self.client.post('/interactions', json=self.body())
        self.assertEqual(duplicate.status_code, 400)
        cancelled = self.client.post('/interactions', json=self.body('cancel'))
        self.assertEqual(cancelled.status_code, 201)
        self.assertEqual(cancelled.json['status'], 'cancelled')
        for changes in ({'user_id': 9999}, {'event_id': 9999}):
            result = self.client.post('/interactions', json=self.body(**changes))
            self.assertEqual(result.status_code, 404)
            self.assertEqual(set(result.json), {'error'})

    def test_invalid_json_and_field_types_do_not_write(self):
        """Reject malformed JSON, missing fields, extra fields, booleans and invalid ratings."""
        invalid = [[], None, 'confirm', {}, {'user_id': self.user},
                   self.body(user_id=True), self.body(event_id='1'), self.body(event_id=1.5),
                   self.body(event_id=0), self.body(user_id=config.API_MAX_ID + 1),
                   self.body(action=[]), self.body(action='unknown'), self.body(rating=5),
                   self.body('rate', rating=True), self.body('rate', rating=0),
                   self.body('rate', rating=6), self.body('rate', rating=4.0),
                   self.body(is_demo=True)]
        for body in invalid:
            with self.subTest(body=body):
                result = self.client.post('/interactions', json=body)
                self.assertEqual(result.status_code, 400)
                self.assertIn('error', result.json)
        result = self.client.post('/interactions', data='{broken', content_type='application/json')
        self.assertEqual(result.status_code, 400)
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM interactions'), 0)

    def test_attendance_rating_and_time_rules(self):
        """Accept past feedback and reject actions outside their allowed time window."""
        self.client.post('/interactions', json=self.body())
        result = self.client.post('/interactions', json=self.body('attended'))
        self.assertEqual(result.status_code, 400)
        ended = support.NOW - timedelta(days=1)
        with self.connection:
            self.connection.execute('UPDATE events SET start_time=?,end_time=? WHERE id=?',
                (database.to_db_text(ended - timedelta(hours=1)), database.to_db_text(ended),
                 self.event))
        result = self.client.post('/interactions', json=self.body('cancel'))
        self.assertEqual(result.status_code, 400)
        result = self.client.post('/interactions', json=self.body('attended'))
        self.assertEqual(result.status_code, 201)
        rated = self.client.post('/interactions', json=self.body('rate', rating=4))
        self.assertEqual(rated.status_code, 201)
        self.assertEqual(rated.json['rating'], 4)
        self.assertEqual(database.get_rating_cache_key(self.connection), (1, 1))
        self.assertEqual(self.client.post('/interactions', json=self.body()).status_code, 400)

    def test_request_connections_close_on_success_and_error(self):
        """Open a fresh connection per request and close it on both successful and failed routes."""
        connections = []
        original = database.get_connection

        def opened(*args, **kwargs):
            """Capture real SQLite handles without changing their lifetime or SQL behavior."""
            connection = original(*args, **kwargs)
            connections.append(connection)
            return connection

        with patch.object(database, 'get_connection', side_effect=opened):
            self.client.get('/health')
            self.client.get('/events')
            self.client.post('/interactions', json=self.body())
        self.assertEqual(len(connections), 3)
        self.assertEqual(len({id(connection) for connection in connections}), 3)
        for connection in connections:
            with self.assertRaises(sqlite3.ProgrammingError):
                connection.execute('SELECT 1')
        error = sqlite3.OperationalError('secret')
        with patch.object(database, 'get_event_records', side_effect=error):
            result = self.client.get('/events', query_string=self.params)
        self.assertEqual(result.status_code, 503)
        self.assertNotIn('secret', result.get_data(as_text=True))

    def test_client_api_and_database_event_parity(self):
        """Use the same classes, order, exact prices and bounds through HTTP and SQLite."""
        with patch.object(api_client.requests, 'get', side_effect=self.bridge_get) as get:
            self.assertTrue(api_client.is_api_available())
            remote, origin = api_client.get_events(self.start, self.end, connection=self.connection)
            self.assertEqual(origin, 'api')
            single, origin = api_client.get_event(self.event, connection=self.connection)
            self.assertEqual(origin, 'api')
            self.assertIsInstance(single, models.ClubEvent)
            start = self.start.replace(hour=11)
            end = self.end - timedelta(hours=12)
            partial, origin = api_client.get_events(start, end, connection=self.connection)
            self.assertTrue(all(start <= event.start < end for event in partial))
        local, origin = api_client.get_events(self.start, self.end, False, self.connection)
        self.assertEqual(origin, 'database')
        self.assertEqual([type(event) for event in remote], [type(event) for event in local])
        for left, right in zip(remote, local):
            self.assertEqual(left.__dict__, right.__dict__)
        self.assertGreater(get.call_count, 0)

    def test_client_read_failures_fall_back_once(self):
        """Handle disconnects, timeouts, non-200, malformed JSON and malformed event rows."""
        errors = [api_client.requests.ConnectionError('offline'),
                  api_client.requests.Timeout('slow')]
        for error in errors:
            with patch.object(api_client.requests, 'get', side_effect=error) as get:
                events, origin = api_client.get_events(self.start, self.end,
                                                        connection=self.connection)
                self.assertEqual((len(events), origin), (3, 'database'))
                self.assertEqual(get.call_count, 1)
        invalid_row = database.get_event_row(self.connection, self.event)
        invalid_row['price_rappen'] = 25.5
        cases = [response(500), response(302), response(200, text='broken'),
                 response(200, {}), response(200, [invalid_row])]
        for reply in cases:
            with patch.object(api_client.requests, 'get', return_value=reply):
                events, origin = api_client.get_events(self.start, self.end,
                                                        connection=self.connection)
                self.assertEqual((len(events), origin), (3, 'database'))
        with patch.object(api_client.requests, 'get', return_value=response(200, [])):
            self.assertEqual(api_client.get_events(self.start, self.end), ([], 'api'))

    def test_health_failure_and_known_offline_skip_requests(self):
        """Reject invalid health documents and skip HTTP when the UI knows it is offline."""
        for reply in (response(503), response(200, {}), response(200, text='bad')):
            with patch.object(api_client.requests, 'get', return_value=reply):
                self.assertFalse(api_client.is_api_available())
        with patch.object(api_client.requests, 'get') as get, \
                patch.object(api_client.requests, 'post') as post:
            api_client.get_events(self.start.date(), self.end.date(), False, self.connection)
            self.assertEqual(api_client.get_event(9999, False, self.connection), (None, 'database'))
            result, origin = api_client.save_interaction(self.user, self.event, 'confirm',
                                                        available=False, connection=self.connection)
            self.assertEqual((result['status'], origin), ('confirmed', 'database'))
            get.assert_not_called()
            post.assert_not_called()

    def test_client_post_and_fallback_share_validation(self):
        """Use the real HTTP state machine, then cancel directly after one connection failure."""
        with patch.object(api_client.requests, 'post', side_effect=self.bridge_post) as post:
            result, origin = api_client.save_interaction(self.user, self.event, 'confirm',
                                                        connection=self.connection)
            self.assertEqual((result['status'], origin), ('confirmed', 'api'))
            with self.assertRaisesRegex(ValueError, 'current event state'):
                api_client.save_interaction(self.user, self.event, 'confirm',
                                            connection=self.connection)
            self.assertEqual(post.call_count, 2)
        with patch.object(api_client.requests, 'post',
                           side_effect=api_client.requests.ConnectionError('offline')) as post:
            result, origin = api_client.save_interaction(self.user, self.event, 'cancel',
                                                        connection=self.connection)
            self.assertEqual((result['status'], origin), ('cancelled', 'database'))
            self.assertEqual(post.call_count, 1)

    def test_post_lost_response_does_not_repeat_a_committed_transition(self):
        """Recover a stored confirmation when the server committed but its response was lost."""
        def committed_then_lost(url, json=None, **options):
            """Run the real route before simulating a transport timeout after its commit."""
            result = self.client.post('/interactions', json=json)
            self.assertEqual(result.status_code, 201)
            raise api_client.requests.Timeout('response lost')

        with patch.object(api_client.requests, 'post', side_effect=committed_then_lost):
            result, origin = api_client.save_interaction(self.user, self.event, 'confirm',
                                                        connection=self.connection)
        self.assertEqual((result['status'], origin), ('confirmed', 'database'))
        self.assertEqual(self.scalar('SELECT COUNT(*) FROM interactions'), 1)

    def test_post_bad_response_and_validation_without_http(self):
        """Fall back on non-201 or malformed success, rejecting invalid inputs before networking."""
        for reply in (response(503), response(201, text='broken'), response(201, {})):
            with self.connection:
                self.connection.execute('DELETE FROM interactions')
            with patch.object(api_client.requests, 'post', return_value=reply):
                result, origin = api_client.save_interaction(self.user, self.event, 'confirm',
                                                            connection=self.connection)
                self.assertEqual((result['status'], origin), ('confirmed', 'database'))
        with patch.object(api_client.requests, 'post') as post:
            with self.assertRaises(ValueError):
                api_client.save_interaction(True, self.event, 'confirm', connection=self.connection)
            post.assert_not_called()

    def test_lost_rating_response_advances_revision_once(self):
        """Recover a committed rating without double-counting feedback or retraining twice."""
        start = support.NOW - timedelta(days=2)
        self.save([support.record(external_id='past-rating', start=start,
                                  end=start + timedelta(hours=1))], include_past=True)
        event_id = self.scalar('SELECT MAX(id) FROM events')
        database.save_interaction(self.connection, self.user, event_id, 'confirm',
                                  now=start - timedelta(days=1))
        database.save_interaction(self.connection, self.user, event_id, 'attended', now=support.NOW)

        def lost(url, json=None, **options):
            """Commit through Flask, then return unusable JSON instead of the stored row."""
            result = self.client.post('/interactions', json=json)
            self.assertEqual(result.status_code, 201)
            return response(201, text='lost body')

        with patch.object(api_client.requests, 'post', side_effect=lost):
            row, origin = api_client.save_interaction(self.user, event_id, 'rate', 5,
                                                       connection=self.connection)
        self.assertEqual((row['rating'], origin), (5, 'database'))
        self.assertEqual(database.get_rating_cache_key(self.connection), (1, 1))

    def test_event_fallback_closes_owned_connection(self):
        """Reject a mismatched detail response and close a client-owned fallback connection."""
        owned = database.get_connection(self.app.config['DATABASE'], uri=True)
        unrelated = database.get_event_row(self.connection, self.event + 1)
        with patch.object(api_client.requests, 'get', return_value=response(200, unrelated)), \
                patch.object(database, 'get_connection', return_value=owned):
            event, origin = api_client.get_event(self.event)
        self.assertEqual((event.event_id, origin), (self.event, 'database'))
        with self.assertRaises(sqlite3.ProgrammingError):
            owned.execute('SELECT 1')
        self.assertTrue(database.user_exists(self.connection, self.user))

    def test_invalid_client_ranges(self):
        """Reject naive/aware mismatches and non-increasing intervals before any network request."""
        with patch.object(api_client.requests, 'get') as get:
            for start, end in ((self.end, self.start), (self.start, self.start),
                                (self.start.replace(tzinfo=timezone.utc), self.end),
                                ('2026-11-03', self.end)):
                with self.assertRaises(ValueError):
                    api_client.get_events(start, end, connection=self.connection)
            get.assert_not_called()
